  Definition prov_D (y e2 p1 : Z) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 3 "S00$y;R+6$e2;R+6$p1;R+6!2+Z+6$y2;R+6!2+Z+6$e0;R+6!2+J!2'^0#2#1&ynz;R!1'E!2'F!2'G#2'H,@+I!2+J!3+9+6#6-IRN$ynz;R+I+6#12!2'C#3!1'K'L#3!2+J!3+9+6#5-IRN$ynz;R+I+6#12!2'M!2'M#2!1,5,N!1,5|4c;#2!3+9+6#4-IRN$~R+I+6!2'R/p;,@2!1,5|22;/p;").
